#!/usr/bin/env python3
"""Lambda function that processes CSV data with timeout handling.
Deployed as a Lambda Function URL for direct HTTP invocation.
"""
import signal
import os
import tempfile
import csv
import json

# Global state for signal handler cleanup
_temp_files = []
_processing_state = {"current_row": 0, "output_buffer": "", "authenticated": False}

def timeout_handler(signum, frame):
    """Handle processing timeout - cleanup and write partial results."""
    # Race condition: handler accesses shared mutable state
    # If signal fires between check and use, state can be corrupted
    if _processing_state["output_buffer"]:
        partial_output = _processing_state["output_buffer"]
        # Write partial results to temp file for later retrieval
        tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.csv', 
                                          dir='/tmp', delete=False)
        tmp.write(partial_output)
        tmp.close()
        _temp_files.append(tmp.name)
    # Reset state unsafely during signal
    _processing_state["current_row"] = 0
    _processing_state["output_buffer"] = ""
    raise TimeoutError("Processing timeout exceeded")

def validate_csv_row(row):
    """Basic validation - checks field count and types."""
    if len(row) > 20:
        return False
    for field in row:
        if len(field) > 4096:
            return False
    return True

def process_csv_data(csv_content, timeout_seconds=5):
    """Process CSV with timeout. Signal handler manages partial state."""
    global _processing_state

    signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(timeout_seconds)

    results = []
    try:
        reader = csv.reader(csv_content.splitlines())
        for i, row in enumerate(reader):
            # VULNERABLE: signal can fire here, between state updates
            _processing_state["current_row"] = i

            if not validate_csv_row(row):
                continue

            # Process row - build output incrementally
            processed = [field.strip().upper() for field in row]
            row_output = ",".join(processed) + "\n"

            # VULNERABLE: signal can fire between these two lines
            # causing output_buffer to have partial/corrupt data
            _processing_state["output_buffer"] += row_output
            results.append(processed)

            # Simulate work that makes race window exploitable
            if any(len(f) > 100 for f in row):
                # Large fields trigger slower path
                _ = json.dumps({"row": i, "data": processed})
    except TimeoutError:
        return {"status": "partial", "rows_processed": _processing_state["current_row"],
                "temp_files": _temp_files.copy()}
    finally:
        signal.alarm(0)

    return {"status": "complete", "rows_processed": len(results), "data": results}

def read_previous_results():
    """Read any partial results from previous timed-out invocations."""
    results = []
    for f in _temp_files:
        if os.path.exists(f):
            with open(f, 'r') as fh:
                # VULNERABLE: reads file that may have been corrupted by race
                results.append(fh.read())
    return results

def handler(event, context):
    """Lambda handler for Function URL invocation."""
    try:
        body = event.get("body", "")
        if event.get("isBase64Encoded", False):
            import base64
            body = base64.b64decode(body).decode('utf-8')

        headers = event.get("headers", {})
        action = headers.get("x-action", "process")

        if action == "retrieve":
            previous = read_previous_results()
            return {"statusCode": 200, 
                    "body": json.dumps({"previous_results": previous})}

        if not body:
            return {"statusCode": 400, "body": "No CSV data provided"}

        timeout = int(headers.get("x-timeout", "5"))
        timeout = min(max(timeout, 1), 30)  # Clamp 1-30s

        result = process_csv_data(body, timeout_seconds=timeout)

        return {"statusCode": 200, "body": json.dumps(result)}
    except Exception as e:
        return {"statusCode": 500, "body": json.dumps({"error": str(e)})}
